INSERT INTO article_cache (article_id, translation, vocab, grammar) VALUES (E'mmdzqqnmabmx', E'{"texts":["The government has decided to allow a university tuition increase for the first time in 15 years. The Ministry of Education made this decision in order to address universities\' financial problems.","Currently, Korean universities are facing a serious money-shortage problem. Student numbers are decreasing, but education costs keep rising. Especially regional universities\' situation is even more difficult.","Tuition can only be raised within the range of the inflation rate (the rate at which prices rise). Universities can raise tuition by about 3% starting this year. However, students and parents are worried that the financial burden will grow.","The government announced that it will expand scholarships for low-income (lower-bracket) students. It also emphasized that universities must use tuition to raise the quality of education.","In the university community, various opinions are emerging about this decision. The universities welcome it, but students are planning protests against it."],"sentences":[{"text":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","translation":"The government has decided to allow a university tuition increase for the first time in 15 years.","vocab":[{"ko":"등록금","en":"tuition","note":""},{"ko":"인상","en":"increase, hike","note":""},{"ko":"허용하다","en":"to permit, allow","note":""}],"analysis":[{"type":"grammar","label":"했어요 (하다 past polite)","exp":"하다 past polite. 하다 → 했어요 = \\"did\\". Here 하기로 했어요 = \\"decided to do\\".","example_in_sentence":"했어요"},{"type":"grammar","label":"~았/었/였어요 (past polite)","exp":"past polite. Hada-stem contracts 하+았 → 했.","example_in_sentence":"했어요"},{"type":"grammar","label":"~(으)로 (means/direction)","exp":"manner / decision marker. (Here triggered by ~기로; the bare (으)로 is part of 기로 \\"decide to\\".)","example_in_sentence":""},{"type":"grammar","label":"~기 (nominalizer)","exp":"verbal nominalizer. 허용하다 → 허용하기 = \\"the act of permitting / allowing\\".","example_in_sentence":"허용하기로"},{"type":"grammar","label":"~만에 (after a duration)","exp":"time elapsed. 15년 → 15년 만에 = \\"after 15 years / for the first time in 15 years\\".","example_in_sentence":"15년 만에"},{"type":"expression","label":"~기로 하다","exp":"decision. <stem> + 기로 하다 = \\"to decide to V\\". 허용하기로 하다 = \\"to decide to permit\\".","example_in_sentence":"허용하기로 했어요"}]},{"text":"교육부는 대학의 재정 문제를 해결하기 위해 이런 결정을 내렸습니다.","translation":"The Ministry of Education made this decision in order to address universities\' financial problems.","vocab":[{"ko":"교육부","en":"Ministry of Education","note":""},{"ko":"재정","en":"finances (institutional)","note":""},{"ko":"해결하다","en":"to solve","note":""},{"ko":"결정","en":"decision","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 내리다 → 내렸습니다 = \\"made / handed down\\".","example_in_sentence":"내렸습니다"},{"type":"grammar","label":"~기 위해(서) (in order to)","exp":"purpose. 해결하다 → 해결하기 위해 = \\"in order to solve\\".","example_in_sentence":"해결하기 위해"}]},{"text":"현재 한국 대학들은 심각한 돈 부족 문제를 겪고 있어요.","translation":"Currently, Korean universities are facing a serious money-shortage problem.","vocab":[{"ko":"심각하다","en":"to be serious","note":""},{"ko":"부족","en":"shortage","note":""},{"ko":"겪다","en":"to undergo, experience","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 겪다 → 겪고 있다 = \\"is experiencing\\".","example_in_sentence":"겪고 있어요"}]},{"text":"학생 수는 줄어들고 있지만 교육 비용은 계속 늘어나고 있습니다.","translation":"Student numbers are decreasing, but education costs keep rising.","vocab":[{"ko":"줄어들다","en":"to decrease","note":""},{"ko":"비용","en":"cost, expense","note":""},{"ko":"늘어나다","en":"to increase","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 줄어들다 → 줄어들고 있다 = \\"is decreasing\\".","example_in_sentence":"줄어들고 있지만"},{"type":"grammar","label":"~지만 (but)","exp":"contrast. 있다 → 있지만 = \\"is, but ~\\".","example_in_sentence":"있지만"},{"type":"grammar","label":"~만 (only)","exp":"limiter. (Regex hit on 지만; the standalone 만 limiter is not used here.)","example_in_sentence":""}]},{"text":"특히 지방 대학들의 상황이 더욱 어려워요.","translation":"Especially regional universities\' situation is even more difficult.","vocab":[{"ko":"지방","en":"region, province","note":""},{"ko":"상황","en":"situation","note":""},{"ko":"더욱","en":"even more","note":""},{"ko":"어렵다","en":"to be difficult","note":"ㅂ-irregular: 어렵+어 → 어려워"}],"analysis":[{"type":"grammar","label":"~히 (adverb suffix, Sino-Korean)","exp":"adverbializer. 특별하다 → 특히 = \\"especially\\".","example_in_sentence":"특히"},{"type":"grammar","label":"ㅂ 불규칙 (ㅂ → 우/오)","exp":"ㅂ-irregular. 어렵다 → 어려워(요). Stem-final ㅂ becomes 우/오 before 아/어.","example_in_sentence":"어려워요"}]},{"text":"등록금은 물가상승률(물건 값이 오르는 비율) 범위 내에서만 올릴 수 있어요.","translation":"Tuition can only be raised within the range of the inflation rate (the rate at which prices rise).","vocab":[{"ko":"물가상승률","en":"inflation rate","note":""},{"ko":"비율","en":"rate, ratio","note":""},{"ko":"범위","en":"range, scope","note":""},{"ko":"올리다","en":"to raise","note":""}],"analysis":[{"type":"grammar","label":"~(으)ㄹ 수 있다/없다 (ability/possibility)","exp":"ability. 올리다 → 올릴 수 있다 = \\"can raise\\".","example_in_sentence":"올릴 수 있어요"},{"type":"grammar","label":"~만 (only)","exp":"limiter. 범위 내에서 → 범위 내에서만 = \\"only within the range\\".","example_in_sentence":"범위 내에서만"}]},{"text":"대학들은 올해부터 약 3% 정도 등록금을 인상할 수 있습니다.","translation":"Universities can raise tuition by about 3% starting this year.","vocab":[{"ko":"정도","en":"about, roughly","note":""}],"analysis":[{"type":"grammar","label":"~(으)ㄹ 수 있다/없다 (ability/possibility)","exp":"ability. 인상하다 → 인상할 수 있다 = \\"can raise\\".","example_in_sentence":"인상할 수 있습니다"},{"type":"grammar","label":"~부터 (from)","exp":"starting from. 올해 → 올해부터 = \\"starting this year\\".","example_in_sentence":"올해부터"},{"type":"grammar","label":"~도 (also)","exp":"inclusive. (Regex hit on 정도; the inclusive 도 particle is not used standalone here.)","example_in_sentence":""}]},{"text":"하지만 학생들과 학부모들은 경제적 부담이 커질 것을 걱정하고 있어요.","translation":"However, students and parents are worried that the financial burden will grow.","vocab":[{"ko":"학부모","en":"parents of students","note":""},{"ko":"부담","en":"burden","note":""},{"ko":"커지다","en":"to become bigger","note":"크다 + 아/어지다"}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 걱정하다 → 걱정하고 있다 = \\"is worrying\\".","example_in_sentence":"걱정하고 있어요"},{"type":"grammar","label":"~지만 (but)","exp":"contrast. (Here the regex matched 하지만 — the standalone conjunction.)","example_in_sentence":"하지만"},{"type":"grammar","label":"~과/와 (with/and)","exp":"formal \\"and\\". 학생들 → 학생들과 학부모들 = \\"students and parents\\".","example_in_sentence":"학생들과 학부모들"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational \\"and\\". (Regex hit on 하고 in 걱정하고.)","example_in_sentence":""},{"type":"grammar","label":"~만 (only)","exp":"limiter. (Regex hit on 하지만; standalone 만 not used.)","example_in_sentence":""}]},{"text":"정부는 저소득층(소득이 적은 계층) 학생들을 위한 장학금을 늘리겠다고 발표했어요.","translation":"The government announced that it will expand scholarships for low-income (lower-bracket) students.","vocab":[{"ko":"저소득층","en":"low-income bracket","note":""},{"ko":"계층","en":"social class, stratum","note":""},{"ko":"장학금","en":"scholarship","note":""}],"analysis":[{"type":"grammar","label":"했어요 (하다 past polite)","exp":"하다 past polite. 발표하다 → 발표했어요 = \\"announced\\".","example_in_sentence":"발표했어요"},{"type":"grammar","label":"~았/었/였어요 (past polite)","exp":"past polite. 발표하다 → 발표했어요.","example_in_sentence":"발표했어요"},{"type":"grammar","label":"~다고 하다 / ~다고 밝히다 / ~다고 강조하다 (indirect declarative + news reporting verbs)","exp":"reported speech with future-intent quote. 늘리겠다 → 늘리겠다고 발표했어요 = \\"announced that (it) will expand\\".","example_in_sentence":"늘리겠다고 발표했어요"},{"type":"grammar","label":"~을/를 위한 (for) [adnominal]","exp":"attributive form of ~을 위해. 학생들을 → 학생들을 위한 장학금 = \\"scholarships for students\\".","example_in_sentence":"학생들을 위한 장학금"}]},{"text":"또한 대학들이 교육의 질을 높이는 데 등록금을 사용해야 한다고 강조했습니다.","translation":"It also emphasized that universities must use tuition to raise the quality of education.","vocab":[{"ko":"또한","en":"also, in addition","note":""},{"ko":"질","en":"quality","note":""},{"ko":"높이다","en":"to raise, elevate","note":""},{"ko":"강조하다","en":"to emphasize","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 강조하다 → 강조했습니다 = \\"emphasized\\".","example_in_sentence":"강조했습니다"},{"type":"grammar","label":"~아/어야 하다/되다 (must)","exp":"obligation. 사용하다 → 사용해야 한다 = \\"must use\\". 하다 contracts to 해야.","example_in_sentence":"사용해야 한다"},{"type":"grammar","label":"~다고 하다 / ~다고 밝히다 / ~다고 강조하다 (indirect declarative + news reporting verbs)","exp":"reported speech. 사용해야 한다 → 사용해야 한다고 강조했습니다 = \\"emphasized that (they) must use\\".","example_in_sentence":"사용해야 한다고 강조했습니다"},{"type":"grammar","label":"~ㄴ/는 데(에) (in V-ing / for V-ing)","exp":"purpose/situation. 높이다 → 높이는 데 = \\"in / for raising\\". 높이는 데 등록금을 사용하다 = \\"use tuition for raising (the quality)\\".","example_in_sentence":"높이는 데"}]},{"text":"대학가에서는 이번 결정에 대해 다양한 의견이 나오고 있어요.","translation":"In the university community, various opinions are emerging about this decision.","vocab":[{"ko":"대학가","en":"college town, university community","note":""},{"ko":"다양하다","en":"to be diverse","note":""},{"ko":"의견","en":"opinion","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 나오다 → 나오고 있다 = \\"is coming out / emerging\\".","example_in_sentence":"나오고 있어요"},{"type":"grammar","label":"~에 대해(서)/대한 (about)","exp":"topical. 결정 → 결정에 대해 = \\"about the decision\\".","example_in_sentence":"결정에 대해"}]},{"text":"대학 측은 환영하지만 학생들은 반대 시위를 계획하고 있습니다.","translation":"The universities welcome it, but students are planning protests against it.","vocab":[{"ko":"측","en":"side, party","note":""},{"ko":"환영하다","en":"to welcome","note":""},{"ko":"반대","en":"opposition","note":""},{"ko":"시위","en":"protest, demonstration","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 계획하다 → 계획하고 있다 = \\"is planning\\".","example_in_sentence":"계획하고 있습니다"},{"type":"grammar","label":"~지만 (but)","exp":"contrast. 환영하다 → 환영하지만 = \\"welcomes, but ~\\".","example_in_sentence":"환영하지만"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational. (Regex hit on 하고 in 계획하고.)","example_in_sentence":""},{"type":"grammar","label":"~만 (only)","exp":"limiter. (Regex hit on 환영하지만; standalone 만 not used.)","example_in_sentence":""},{"type":"grammar","label":"~(으)ㄹ 전망이다 / 계획이다 / 방침이다 / 예정이다 (is expected / planned to)","exp":"formal news future intent. (Here triggered by 계획하고 있다 — the periphrastic version.)","example_in_sentence":"계획하고 있습니다"}]}],"version":"s5"}', E'[{"ko":"등록금","en":"tuition","note":""},{"ko":"인상","en":"increase, hike","note":""},{"ko":"허용하다","en":"to permit, allow","note":""},{"ko":"교육부","en":"Ministry of Education","note":""},{"ko":"재정","en":"finances (institutional)","note":""},{"ko":"해결하다","en":"to solve","note":""},{"ko":"결정","en":"decision","note":""},{"ko":"심각하다","en":"to be serious","note":""},{"ko":"부족","en":"shortage","note":""},{"ko":"겪다","en":"to undergo, experience","note":""},{"ko":"줄어들다","en":"to decrease","note":""},{"ko":"비용","en":"cost, expense","note":""},{"ko":"늘어나다","en":"to increase","note":""},{"ko":"지방","en":"region, province","note":""},{"ko":"상황","en":"situation","note":""},{"ko":"더욱","en":"even more","note":""},{"ko":"어렵다","en":"to be difficult","note":"ㅂ-irregular: 어렵+어 → 어려워"},{"ko":"물가상승률","en":"inflation rate","note":""},{"ko":"비율","en":"rate, ratio","note":""},{"ko":"범위","en":"range, scope","note":""},{"ko":"올리다","en":"to raise","note":""},{"ko":"정도","en":"about, roughly","note":""},{"ko":"학부모","en":"parents of students","note":""},{"ko":"부담","en":"burden","note":""},{"ko":"커지다","en":"to become bigger","note":"크다 + 아/어지다"},{"ko":"저소득층","en":"low-income bracket","note":""},{"ko":"계층","en":"social class, stratum","note":""},{"ko":"장학금","en":"scholarship","note":""},{"ko":"또한","en":"also, in addition","note":""},{"ko":"질","en":"quality","note":""},{"ko":"높이다","en":"to raise, elevate","note":""},{"ko":"강조하다","en":"to emphasize","note":""},{"ko":"대학가","en":"college town, university community","note":""},{"ko":"다양하다","en":"to be diverse","note":""},{"ko":"의견","en":"opinion","note":""},{"ko":"측","en":"side, party","note":""},{"ko":"환영하다","en":"to welcome","note":""},{"ko":"반대","en":"opposition","note":""},{"ko":"시위","en":"protest, demonstration","note":""}]', E'{"patterns":[{"name":"했어요 (하다 past polite)","level":"Intermediate","exp":"하다 past polite. 하다 → 했어요 = \\"did\\". Here 하기로 했어요 = \\"decided to do\\".","ex_ko":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","ex_en":"The government has decided to allow a university tuition increase for the first time in 15 years."},{"name":"~았/었/였어요 (past polite)","level":"Intermediate","exp":"past polite. Hada-stem contracts 하+았 → 했.","ex_ko":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","ex_en":"The government has decided to allow a university tuition increase for the first time in 15 years."},{"name":"~(으)로 (means/direction)","level":"Intermediate","exp":"manner / decision marker. (Here triggered by ~기로; the bare (으)로 is part of 기로 \\"decide to\\".)","ex_ko":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","ex_en":"The government has decided to allow a university tuition increase for the first time in 15 years."},{"name":"~기 (nominalizer)","level":"Intermediate","exp":"verbal nominalizer. 허용하다 → 허용하기 = \\"the act of permitting / allowing\\".","ex_ko":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","ex_en":"The government has decided to allow a university tuition increase for the first time in 15 years."},{"name":"~만에 (after a duration)","level":"Intermediate","exp":"time elapsed. 15년 → 15년 만에 = \\"after 15 years / for the first time in 15 years\\".","ex_ko":"정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.","ex_en":"The government has decided to allow a university tuition increase for the first time in 15 years."},{"name":"~았/었/였습니다 (past formal)","level":"Intermediate","exp":"past formal-polite. 내리다 → 내렸습니다 = \\"made / handed down\\".","ex_ko":"교육부는 대학의 재정 문제를 해결하기 위해 이런 결정을 내렸습니다.","ex_en":"The Ministry of Education made this decision in order to address universities\' financial problems."},{"name":"~기 위해(서) (in order to)","level":"Intermediate","exp":"purpose. 해결하다 → 해결하기 위해 = \\"in order to solve\\".","ex_ko":"교육부는 대학의 재정 문제를 해결하기 위해 이런 결정을 내렸습니다.","ex_en":"The Ministry of Education made this decision in order to address universities\' financial problems."},{"name":"~고 있다 (continuous)","level":"Intermediate","exp":"progressive. 나오다 → 나오고 있다 = \\"is coming out / emerging\\".","ex_ko":"현재 한국 대학들은 심각한 돈 부족 문제를 겪고 있어요.","ex_en":"Currently, Korean universities are facing a serious money-shortage problem."},{"name":"~지만 (but)","level":"Intermediate","exp":"contrast. (Here the regex matched 하지만 — the standalone conjunction.)","ex_ko":"학생 수는 줄어들고 있지만 교육 비용은 계속 늘어나고 있습니다.","ex_en":"Student numbers are decreasing, but education costs keep rising."},{"name":"~만 (only)","level":"Intermediate","exp":"limiter. (Regex hit on 지만; the standalone 만 limiter is not used here.)","ex_ko":"학생 수는 줄어들고 있지만 교육 비용은 계속 늘어나고 있습니다.","ex_en":"Student numbers are decreasing, but education costs keep rising."},{"name":"~히 (adverb suffix, Sino-Korean)","level":"Intermediate","exp":"adverbializer. 특별하다 → 특히 = \\"especially\\".","ex_ko":"특히 지방 대학들의 상황이 더욱 어려워요.","ex_en":"Especially regional universities\' situation is even more difficult."},{"name":"ㅂ 불규칙 (ㅂ → 우/오)","level":"Intermediate","exp":"ㅂ-irregular. 어렵다 → 어려워(요). Stem-final ㅂ becomes 우/오 before 아/어.","ex_ko":"특히 지방 대학들의 상황이 더욱 어려워요.","ex_en":"Especially regional universities\' situation is even more difficult."},{"name":"~(으)ㄹ 수 있다/없다 (ability/possibility)","level":"Intermediate","exp":"ability. 인상하다 → 인상할 수 있다 = \\"can raise\\".","ex_ko":"등록금은 물가상승률(물건 값이 오르는 비율) 범위 내에서만 올릴 수 있어요.","ex_en":"Tuition can only be raised within the range of the inflation rate (the rate at which prices rise)."},{"name":"~부터 (from)","level":"Intermediate","exp":"starting from. 올해 → 올해부터 = \\"starting this year\\".","ex_ko":"대학들은 올해부터 약 3% 정도 등록금을 인상할 수 있습니다.","ex_en":"Universities can raise tuition by about 3% starting this year."},{"name":"~도 (also)","level":"Intermediate","exp":"inclusive. (Regex hit on 정도; the inclusive 도 particle is not used standalone here.)","ex_ko":"대학들은 올해부터 약 3% 정도 등록금을 인상할 수 있습니다.","ex_en":"Universities can raise tuition by about 3% starting this year."}]}') ON CONFLICT (article_id) DO UPDATE SET translation = EXCLUDED.translation, vocab = COALESCE(EXCLUDED.vocab, article_cache.vocab), grammar = COALESCE(EXCLUDED.grammar, article_cache.grammar);
INSERT INTO article_cache (article_id, translation, vocab, grammar) VALUES (E'mmfstli3xitg', E'{"texts":["The age at which Korean young people get married keeps getting later. According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women.","This is 2.1 years later for men and 2.3 years later for women compared to ten years ago. Especially in Seoul and the metropolitan area, the trend of marrying later has grown stronger.","High housing prices and difficulty finding jobs are cited as reasons marriage is being delayed. The analysis is that the younger generation is putting off marriage because of financial burdens.","Experts warned that if this phenomenon continues, the low-birthrate problem could become more serious. The government said it needs to expand housing support for newlyweds and job-creation policies.","Meanwhile, \\"solo culture\\" is also spreading among the younger generation. As young people who enjoy living alone increase, thoughts about marriage have also changed greatly."],"sentences":[{"text":"한국 청년들이 결혼하는 나이가 계속 늦어지고 있어요.","translation":"The age at which Korean young people get married keeps getting later.","vocab":[{"ko":"청년","en":"young person, youth","note":""},{"ko":"결혼하다","en":"to get married","note":""},{"ko":"늦어지다","en":"to become later, be delayed","note":"늦다 + 아/어지다"}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 늦어지다 → 늦어지고 있다 = \\"is getting later\\".","example_in_sentence":"늦어지고 있어요"},{"type":"grammar","label":"~아/어지다 (passive / become)","exp":"change-of-state. 늦다 → 늦어지다 = \\"to become late / be delayed\\".","example_in_sentence":"늦어지고"}]},{"text":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","translation":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women.","vocab":[{"ko":"통계청","en":"Statistics Korea","note":""},{"ko":"평균","en":"average","note":""},{"ko":"초혼","en":"first marriage","note":""},{"ko":"연령","en":"age (formal)","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 나타나다 → 나타났습니다 = \\"appeared / was shown\\".","example_in_sentence":"나타났습니다"},{"type":"grammar","label":"~(으)면 (if/when)","exp":"conditional. (Here triggered by 따르면; the conditional sense is preserved as \\"if you follow / according to\\".)","example_in_sentence":"따르면"},{"type":"grammar","label":"~(으)로 (means/direction)","exp":"result/manner marker. 31.3세 → 31.3세로 나타났다 = \\"appeared as 31.3\\".","example_in_sentence":"31.3세로"},{"type":"grammar","label":"~에 따르면 (according to)","exp":"evidential. 자료 → 자료에 따르면 = \\"according to the data\\".","example_in_sentence":"자료에 따르면"},{"type":"grammar","label":"~(으)로 보이다 / 추정되다 / 분석되다 / 평가되다 (news evaluative passives)","exp":"news-register evaluative. 31.3세로 나타났다 = \\"turned out to be 31.3 / was shown as 31.3\\".","example_in_sentence":"31.3세로 나타났습니다"}]},{"text":"이는 10년 전보다 남성 2.1세, 여성 2.3세 늦어진 것이에요.","translation":"This is 2.1 years later for men and 2.3 years later for women compared to ten years ago.","vocab":[{"ko":"전","en":"before, ago","note":""}],"analysis":[{"type":"grammar","label":"~보다 (comparison)","exp":"comparison. 10년 전 → 10년 전보다 = \\"compared to / more than 10 years ago\\".","example_in_sentence":"10년 전보다"}]},{"text":"특히 서울과 수도권에서는 더 늦게 결혼하는 경향이 강해졌습니다.","translation":"Especially in Seoul and the metropolitan area, the trend of marrying later has grown stronger.","vocab":[{"ko":"특히","en":"especially","note":""},{"ko":"수도권","en":"metropolitan area","note":""},{"ko":"경향","en":"trend, tendency","note":""},{"ko":"강해지다","en":"to become stronger","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 강해지다 → 강해졌습니다 = \\"became stronger\\".","example_in_sentence":"강해졌습니다"},{"type":"grammar","label":"~게 (adverbializer suffix)","exp":"adverbializer. 늦다 → 늦게 = \\"late, lately\\".","example_in_sentence":"늦게"},{"type":"grammar","label":"~히 (adverb suffix, Sino-Korean)","exp":"adverbializer. 특별하다 → 특히 = \\"especially\\".","example_in_sentence":"특히"},{"type":"grammar","label":"~과/와 (with/and)","exp":"formal \\"and\\". 서울 → 서울과 수도권 = \\"Seoul and the metro area\\".","example_in_sentence":"서울과 수도권"}]},{"text":"결혼이 늦어지는 이유로는 높은 집값과 취업 어려움이 꼽혀요.","translation":"High housing prices and difficulty finding jobs are cited as reasons marriage is being delayed.","vocab":[{"ko":"이유","en":"reason","note":""},{"ko":"집값","en":"housing prices","note":""},{"ko":"취업","en":"employment","note":""},{"ko":"꼽히다","en":"to be cited / picked","note":"passive of 꼽다"}],"analysis":[{"type":"grammar","label":"~과/와 (with/and)","exp":"formal \\"and\\". 집값 → 집값과 취업 어려움 = \\"housing prices and job difficulty\\".","example_in_sentence":"집값과 취업 어려움"},{"type":"grammar","label":"~아/어지다 (passive / become)","exp":"change-of-state. 늦다 → 늦어지다 → 늦어지는 = \\"that gets delayed\\".","example_in_sentence":"늦어지는"}]},{"text":"젊은 세대들이 경제적 부담 때문에 결혼을 미루고 있다는 분석입니다.","translation":"The analysis is that the younger generation is putting off marriage because of financial burdens.","vocab":[{"ko":"세대","en":"generation","note":""},{"ko":"부담","en":"burden","note":""},{"ko":"미루다","en":"to put off, postpone","note":""},{"ko":"분석","en":"analysis","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 미루다 → 미루고 있다 = \\"is postponing\\".","example_in_sentence":"미루고 있다는"},{"type":"grammar","label":"~ 때문에 (because of N)","exp":"because of (noun). 부담 → 부담 때문에 = \\"because of the burden\\".","example_in_sentence":"부담 때문에"},{"type":"grammar","label":"~ㄴ/는다는 / ~라는 + N (the claim/fact/idea that)","exp":"attributive of reported clause. 미루고 있다 → 미루고 있다는 분석 = \\"the analysis that (they) are postponing\\".","example_in_sentence":"미루고 있다는 분석"},{"type":"grammar","label":"~적 (-ic / -al adjective suffix)","exp":"Sino-Korean → adjective. 경제 → 경제적 = \\"economic\\".","example_in_sentence":"경제적 부담"}]},{"text":"전문가들은 이런 현상이 계속되면 저출산 문제가 더 심각해질 수 있다고 경고했어요.","translation":"Experts warned that if this phenomenon continues, the low-birthrate problem could become more serious.","vocab":[{"ko":"현상","en":"phenomenon","note":""},{"ko":"저출산","en":"low birthrate","note":""},{"ko":"심각해지다","en":"to become serious","note":""},{"ko":"경고하다","en":"to warn","note":""}],"analysis":[{"type":"grammar","label":"했어요 (하다 past polite)","exp":"하다 past polite. 경고하다 → 경고했어요 = \\"warned\\".","example_in_sentence":"경고했어요"},{"type":"grammar","label":"~았/었/였어요 (past polite)","exp":"past polite. 경고하다 → 경고했어요.","example_in_sentence":"경고했어요"},{"type":"grammar","label":"~(으)ㄹ 수 있다/없다 (ability/possibility)","exp":"possibility. 심각해지다 → 심각해질 수 있다 = \\"could become serious\\".","example_in_sentence":"심각해질 수 있다고"},{"type":"grammar","label":"~(으)면 (if/when)","exp":"conditional. 계속되다 → 계속되면 = \\"if (it) continues\\".","example_in_sentence":"계속되면"},{"type":"expression","label":"~다고 하다 / ~다고 경고하다","exp":"reported speech with warning verb. <clause> + 다고 경고했어요 = \\"warned that ~\\".","example_in_sentence":"있다고 경고했어요"}]},{"text":"정부는 신혼부부 주택 지원과 일자리 창출 정책을 늘려야 한다고 말했습니다.","translation":"The government said it needs to expand housing support for newlyweds and job-creation policies.","vocab":[{"ko":"신혼부부","en":"newlywed couple","note":""},{"ko":"주택 지원","en":"housing support","note":""},{"ko":"일자리 창출","en":"job creation","note":""},{"ko":"늘리다","en":"to increase","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 말하다 → 말했습니다 = \\"said\\".","example_in_sentence":"말했습니다"},{"type":"grammar","label":"~과/와 (with/and)","exp":"formal \\"and\\". 주택 지원 → 주택 지원과 일자리 창출 = \\"housing support and job creation\\".","example_in_sentence":"주택 지원과 일자리 창출"},{"type":"grammar","label":"~다고 하다 / ~다고 밝히다 / ~다고 강조하다 (indirect declarative + news reporting verbs)","exp":"reported speech. 늘려야 한다 → 늘려야 한다고 말했습니다 = \\"said that (they) must increase\\".","example_in_sentence":"늘려야 한다고 말했습니다"},{"type":"expression","label":"~아/어야 하다","exp":"obligation. 늘리다 → 늘려야 한다 = \\"must increase / should increase\\".","example_in_sentence":"늘려야 한다"}]},{"text":"한편, 젊은 세대 사이에서는 \'솔로 문화\'도 확산되고 있어요.","translation":"Meanwhile, \\"solo culture\\" is also spreading among the younger generation.","vocab":[{"ko":"한편","en":"meanwhile, on the other hand","note":""},{"ko":"사이","en":"between, among","note":""},{"ko":"확산되다","en":"to spread","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 확산되다 → 확산되고 있다 = \\"is spreading\\".","example_in_sentence":"확산되고 있어요"},{"type":"grammar","label":"~(으)로 (means/direction)","exp":"means / direction. (Regex hit on 솔로 / 사이에서는; the (으)로 particle is not separately present.)","example_in_sentence":""}]},{"text":"혼자 사는 것을 즐기는 청년들이 늘어나면서 결혼에 대한 생각도 많이 바뀌었습니다.","translation":"As young people who enjoy living alone increase, thoughts about marriage have also changed greatly.","vocab":[{"ko":"혼자","en":"alone","note":""},{"ko":"즐기다","en":"to enjoy","note":""},{"ko":"늘어나다","en":"to increase","note":""},{"ko":"바뀌다","en":"to change","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 바뀌다 → 바뀌었습니다 = \\"changed\\".","example_in_sentence":"바뀌었습니다"},{"type":"grammar","label":"~(으)면서 (while)","exp":"simultaneous. 늘어나다 → 늘어나면서 = \\"while increasing / as (they) increase\\".","example_in_sentence":"늘어나면서"},{"type":"grammar","label":"~도 (also)","exp":"inclusive. 생각 → 생각도 = \\"thoughts, also\\".","example_in_sentence":"생각도"},{"type":"grammar","label":"~에 대해(서)/대한 (about)","exp":"topical. 결혼 → 결혼에 대한 생각 = \\"thoughts about marriage\\".","example_in_sentence":"결혼에 대한"},{"type":"grammar","label":"~에 대한 N (about/regarding N) [adnominal]","exp":"attributive form. 결혼에 대한 생각 = \\"thoughts regarding marriage\\".","example_in_sentence":"결혼에 대한 생각"}]}],"version":"s5"}', E'[{"ko":"청년","en":"young person, youth","note":""},{"ko":"결혼하다","en":"to get married","note":""},{"ko":"늦어지다","en":"to become later, be delayed","note":"늦다 + 아/어지다"},{"ko":"통계청","en":"Statistics Korea","note":""},{"ko":"평균","en":"average","note":""},{"ko":"초혼","en":"first marriage","note":""},{"ko":"연령","en":"age (formal)","note":""},{"ko":"전","en":"before, ago","note":""},{"ko":"특히","en":"especially","note":""},{"ko":"수도권","en":"metropolitan area","note":""},{"ko":"경향","en":"trend, tendency","note":""},{"ko":"강해지다","en":"to become stronger","note":""},{"ko":"이유","en":"reason","note":""},{"ko":"집값","en":"housing prices","note":""},{"ko":"취업","en":"employment","note":""},{"ko":"꼽히다","en":"to be cited / picked","note":"passive of 꼽다"},{"ko":"세대","en":"generation","note":""},{"ko":"부담","en":"burden","note":""},{"ko":"미루다","en":"to put off, postpone","note":""},{"ko":"분석","en":"analysis","note":""},{"ko":"현상","en":"phenomenon","note":""},{"ko":"저출산","en":"low birthrate","note":""},{"ko":"심각해지다","en":"to become serious","note":""},{"ko":"경고하다","en":"to warn","note":""},{"ko":"신혼부부","en":"newlywed couple","note":""},{"ko":"주택 지원","en":"housing support","note":""},{"ko":"일자리 창출","en":"job creation","note":""},{"ko":"늘리다","en":"to increase","note":""},{"ko":"한편","en":"meanwhile, on the other hand","note":""},{"ko":"사이","en":"between, among","note":""},{"ko":"확산되다","en":"to spread","note":""},{"ko":"혼자","en":"alone","note":""},{"ko":"즐기다","en":"to enjoy","note":""},{"ko":"늘어나다","en":"to increase","note":""},{"ko":"바뀌다","en":"to change","note":""}]', E'{"patterns":[{"name":"~고 있다 (continuous)","level":"Intermediate","exp":"progressive. 늦어지다 → 늦어지고 있다 = \\"is getting later\\".","ex_ko":"한국 청년들이 결혼하는 나이가 계속 늦어지고 있어요.","ex_en":"The age at which Korean young people get married keeps getting later."},{"name":"~아/어지다 (passive / become)","level":"Intermediate","exp":"change-of-state. 늦다 → 늦어지다 = \\"to become late / be delayed\\".","ex_ko":"한국 청년들이 결혼하는 나이가 계속 늦어지고 있어요.","ex_en":"The age at which Korean young people get married keeps getting later."},{"name":"~았/었/였습니다 (past formal)","level":"Intermediate","exp":"past formal-polite. 나타나다 → 나타났습니다 = \\"appeared / was shown\\".","ex_ko":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","ex_en":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women."},{"name":"~(으)면 (if/when)","level":"Intermediate","exp":"conditional. (Here triggered by 따르면; the conditional sense is preserved as \\"if you follow / according to\\".)","ex_ko":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","ex_en":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women."},{"name":"~(으)로 (means/direction)","level":"Intermediate","exp":"means / direction. (Regex hit on 솔로 / 사이에서는; the (으)로 particle is not separately present.)","ex_ko":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","ex_en":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women."},{"name":"~에 따르면 (according to)","level":"Intermediate","exp":"evidential. 자료 → 자료에 따르면 = \\"according to the data\\".","ex_ko":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","ex_en":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women."},{"name":"~(으)로 보이다 / 추정되다 / 분석되다 / 평가되다 (news evaluative passives)","level":"Intermediate","exp":"news-register evaluative. 31.3세로 나타났다 = \\"turned out to be 31.3 / was shown as 31.3\\".","ex_ko":"2025년 통계청 자료에 따르면, 평균 초혼 연령(처음 결혼하는 나이)이 남성 33.7세, 여성 31.3세로 나타났습니다.","ex_en":"According to 2025 Statistics Korea data, the average age at first marriage was found to be 33.7 for men and 31.3 for women."},{"name":"~보다 (comparison)","level":"Intermediate","exp":"comparison. 10년 전 → 10년 전보다 = \\"compared to / more than 10 years ago\\".","ex_ko":"이는 10년 전보다 남성 2.1세, 여성 2.3세 늦어진 것이에요.","ex_en":"This is 2.1 years later for men and 2.3 years later for women compared to ten years ago."},{"name":"~게 (adverbializer suffix)","level":"Intermediate","exp":"adverbializer. 늦다 → 늦게 = \\"late, lately\\".","ex_ko":"특히 서울과 수도권에서는 더 늦게 결혼하는 경향이 강해졌습니다.","ex_en":"Especially in Seoul and the metropolitan area, the trend of marrying later has grown stronger."},{"name":"~히 (adverb suffix, Sino-Korean)","level":"Intermediate","exp":"adverbializer. 특별하다 → 특히 = \\"especially\\".","ex_ko":"특히 서울과 수도권에서는 더 늦게 결혼하는 경향이 강해졌습니다.","ex_en":"Especially in Seoul and the metropolitan area, the trend of marrying later has grown stronger."},{"name":"~과/와 (with/and)","level":"Intermediate","exp":"formal \\"and\\". 주택 지원 → 주택 지원과 일자리 창출 = \\"housing support and job creation\\".","ex_ko":"특히 서울과 수도권에서는 더 늦게 결혼하는 경향이 강해졌습니다.","ex_en":"Especially in Seoul and the metropolitan area, the trend of marrying later has grown stronger."},{"name":"~ 때문에 (because of N)","level":"Intermediate","exp":"because of (noun). 부담 → 부담 때문에 = \\"because of the burden\\".","ex_ko":"젊은 세대들이 경제적 부담 때문에 결혼을 미루고 있다는 분석입니다.","ex_en":"The analysis is that the younger generation is putting off marriage because of financial burdens."},{"name":"~ㄴ/는다는 / ~라는 + N (the claim/fact/idea that)","level":"Intermediate","exp":"attributive of reported clause. 미루고 있다 → 미루고 있다는 분석 = \\"the analysis that (they) are postponing\\".","ex_ko":"젊은 세대들이 경제적 부담 때문에 결혼을 미루고 있다는 분석입니다.","ex_en":"The analysis is that the younger generation is putting off marriage because of financial burdens."},{"name":"~적 (-ic / -al adjective suffix)","level":"Intermediate","exp":"Sino-Korean → adjective. 경제 → 경제적 = \\"economic\\".","ex_ko":"젊은 세대들이 경제적 부담 때문에 결혼을 미루고 있다는 분석입니다.","ex_en":"The analysis is that the younger generation is putting off marriage because of financial burdens."},{"name":"했어요 (하다 past polite)","level":"Intermediate","exp":"하다 past polite. 경고하다 → 경고했어요 = \\"warned\\".","ex_ko":"전문가들은 이런 현상이 계속되면 저출산 문제가 더 심각해질 수 있다고 경고했어요.","ex_en":"Experts warned that if this phenomenon continues, the low-birthrate problem could become more serious."}]}') ON CONFLICT (article_id) DO UPDATE SET translation = EXCLUDED.translation, vocab = COALESCE(EXCLUDED.vocab, article_cache.vocab), grammar = COALESCE(EXCLUDED.grammar, article_cache.grammar);
INSERT INTO article_cache (article_id, translation, vocab, grammar) VALUES (E'mmivyelwpb4w', E'{"texts":["The Indian government announced plans to introduce its own digital currency (Central Bank Digital Currency, CBDC). This new digital money is scheduled to be usable nationwide starting at the end of this year.","India is currently the country with the largest population in the world. About 1.4 billion people live there. The government intends to make financial services (saving and sending money) more convenient with digital currency.","China and the European Union are also already preparing digital currencies. Experts say that digital currency will be the money of the future. However, the issue of personal information protection is still a concern.","The Korean government is also continuing its research on digital currency. The Bank of Korea (the central bank) announced that it plans to begin pilot operations next year. The whole world is preparing for a new era of money."],"sentences":[{"text":"인도 정부가 자체 디지털 화폐(Central Bank Digital Currency, CBDC) 도입 계획을 발표했어요.","translation":"The Indian government announced plans to introduce its own digital currency (Central Bank Digital Currency, CBDC).","vocab":[{"ko":"정부","en":"government","note":""},{"ko":"자체","en":"own, in-house","note":""},{"ko":"화폐","en":"currency","note":""},{"ko":"도입","en":"introduction, adoption","note":""}],"analysis":[{"type":"grammar","label":"했어요 (하다 past polite)","exp":"하다 past polite. 발표하다 → 발표했어요 = \\"announced\\".","example_in_sentence":"발표했어요"},{"type":"grammar","label":"~았/었/였어요 (past polite)","exp":"past polite. Vowel contraction with 하: 하+았 → 했.","example_in_sentence":"발표했어요"},{"type":"grammar","label":"~도 (also)","exp":"inclusive. (Regex hit on 도입 — false-positive on the 도 syllable; the inclusive particle is not used here.)","example_in_sentence":""}]},{"text":"이 새로운 디지털 돈은 올해 말부터 전국에서 사용할 수 있을 예정입니다.","translation":"This new digital money is scheduled to be usable nationwide starting at the end of this year.","vocab":[{"ko":"새롭다","en":"to be new","note":"ㅂ-irregular: 새롭+은 → 새로운"},{"ko":"올해","en":"this year","note":""},{"ko":"전국","en":"the whole country","note":""}],"analysis":[{"type":"grammar","label":"~(으)ㄹ 수 있다/없다 (ability/possibility)","exp":"ability. 사용하다 → 사용할 수 있다 = \\"can use / can be used\\". <stem> + (으)ㄹ 수 있다.","example_in_sentence":"사용할 수 있을"},{"type":"grammar","label":"~롭다 (-ous / adjective formative)","exp":"noun→adjective. 새 → 새롭다 → 새로운 = \\"new (modifier)\\".","example_in_sentence":"새로운 디지털 돈"},{"type":"grammar","label":"~에서 (location/source)","exp":"location. 전국 → 전국에서 = \\"throughout the country\\".","example_in_sentence":"전국에서"},{"type":"grammar","label":"~부터 (from)","exp":"starting from. 올해 말 → 올해 말부터 = \\"from the end of this year\\".","example_in_sentence":"올해 말부터"},{"type":"grammar","label":"~(으)ㄹ 전망이다 / 계획이다 / 방침이다 / 예정이다 (is expected / planned to)","exp":"formal future intent. 사용할 수 있다 → 사용할 수 있을 예정이다 = \\"is scheduled to be usable\\".","example_in_sentence":"사용할 수 있을 예정입니다"}]},{"text":"인도는 현재 세계에서 가장 많은 인구를 가진 나라예요.","translation":"India is currently the country with the largest population in the world.","vocab":[{"ko":"현재","en":"currently","note":""},{"ko":"세계","en":"world","note":""},{"ko":"인구","en":"population","note":""}],"analysis":[{"type":"grammar","label":"~에서 (location/source)","exp":"location/source. 세계 → 세계에서 = \\"in the world\\".","example_in_sentence":"세계에서"},{"type":"expression","label":"가장 ~","exp":"superlative. 가장 많은 = \\"the most / largest\\".","example_in_sentence":"가장 많은 인구"}]},{"text":"약 14억 명의 사람들이 살고 있습니다.","translation":"About 1.4 billion people live there.","vocab":[{"ko":"약","en":"about, approximately","note":""},{"ko":"억","en":"hundred million","note":"14억 = 1.4 billion"}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 살다 → 살고 있다 → 살고 있습니다 = \\"are living\\".","example_in_sentence":"살고 있습니다"}]},{"text":"정부는 디지털 화폐로 금융 서비스(돈을 저축하고 보내는 일)를 더 편리하게 만들려고 해요.","translation":"The government intends to make financial services (saving and sending money) more convenient with digital currency.","vocab":[{"ko":"금융","en":"finance","note":""},{"ko":"저축하다","en":"to save (money)","note":""},{"ko":"편리하다","en":"to be convenient","note":""}],"analysis":[{"type":"grammar","label":"~(으)려고 (intention)","exp":"intention. 만들다 → 만들려고 (하다) = \\"intends to make\\".","example_in_sentence":"만들려고 해요"},{"type":"grammar","label":"~게 하다 (causative)","exp":"periphrastic causative. 편리하다 → 편리하게 만들다 = \\"to make convenient\\". <stem> + 게 만들다/하다.","example_in_sentence":"편리하게 만들려고"},{"type":"grammar","label":"~(으)로 (means/direction)","exp":"means. 디지털 화폐 → 디지털 화폐로 = \\"with / by means of digital currency\\".","example_in_sentence":"디지털 화폐로"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational \\"and\\". 저축하다 → 저축하고 보내는 = \\"save and send\\".","example_in_sentence":"저축하고 보내는"}]},{"text":"중국과 유럽연합도 이미 디지털 화폐를 준비하고 있어요.","translation":"China and the European Union are also already preparing digital currencies.","vocab":[{"ko":"유럽연합","en":"European Union","note":""},{"ko":"이미","en":"already","note":""},{"ko":"준비하다","en":"to prepare","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 준비하다 → 준비하고 있다 = \\"is preparing\\".","example_in_sentence":"준비하고 있어요"},{"type":"grammar","label":"~과/와 (with/and)","exp":"formal \\"and\\". 중국 → 중국과 유럽연합 = \\"China and the EU\\".","example_in_sentence":"중국과 유럽연합"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational \\"and\\". (Regex hit on 하고 in 준비하고.)","example_in_sentence":""},{"type":"grammar","label":"~도 (also)","exp":"inclusive. 유럽연합 → 유럽연합도 = \\"the EU, also\\".","example_in_sentence":"유럽연합도"}]},{"text":"전문가들은 디지털 화폐가 미래의 돈이 될 것이라고 말합니다.","translation":"Experts say that digital currency will be the money of the future.","vocab":[{"ko":"미래","en":"future","note":""}],"analysis":[{"type":"grammar","label":"~(이)라고 하다 / ~(이)라고 밝히다 (indirect copula/name + news reporting)","exp":"reported speech (identification). 될 것이다 → 될 것이라고 말합니다 = \\"says that (it) will become\\".","example_in_sentence":"될 것이라고 말합니다"},{"type":"expression","label":"~(이)ㄹ 것이다 (future/assumption)","exp":"future tense. 되다 → 될 것이다 = \\"will become\\".","example_in_sentence":"될 것이라고"}]},{"text":"하지만 개인 정보 보호 문제는 여전히 걱정거리예요.","translation":"However, the issue of personal information protection is still a concern.","vocab":[{"ko":"개인","en":"individual, personal","note":""},{"ko":"보호","en":"protection","note":""},{"ko":"여전히","en":"still, as before","note":""},{"ko":"걱정거리","en":"something to worry about","note":""}],"analysis":[{"type":"grammar","label":"~지만 (but)","exp":"contrast. (Here the regex matched on 하지만 — the standalone conjunction \\"however\\".)","example_in_sentence":"하지만"},{"type":"grammar","label":"~히 (adverb suffix, Sino-Korean)","exp":"adverbializer. 여전 → 여전히 = \\"still / as before\\".","example_in_sentence":"여전히"},{"type":"grammar","label":"~만 (only)","exp":"limiter. (Regex hit on 하지만; the limiter 만 is not used here.)","example_in_sentence":""}]},{"text":"한국 정부도 디지털 화폐 연구를 계속하고 있어요.","translation":"The Korean government is also continuing its research on digital currency.","vocab":[{"ko":"연구","en":"research","note":""},{"ko":"계속하다","en":"to continue","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 계속하다 → 계속하고 있다 = \\"is continuing\\".","example_in_sentence":"계속하고 있어요"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational. (Regex hit on 하고 in 계속하고.)","example_in_sentence":""},{"type":"grammar","label":"~도 (also)","exp":"inclusive. 한국 정부 → 한국 정부도 = \\"the Korean government, also\\".","example_in_sentence":"한국 정부도"}]},{"text":"한국은행(중앙은행)은 내년에 시험 운영을 시작할 계획이라고 발표했습니다.","translation":"The Bank of Korea (the central bank) announced that it plans to begin pilot operations next year.","vocab":[{"ko":"내년","en":"next year","note":""},{"ko":"시험 운영","en":"pilot run, trial operation","note":""},{"ko":"시작하다","en":"to start","note":""}],"analysis":[{"type":"grammar","label":"~았/었/였습니다 (past formal)","exp":"past formal-polite. 발표하다 → 발표했습니다 = \\"announced\\".","example_in_sentence":"발표했습니다"},{"type":"grammar","label":"~(이)라고 하다 / ~(이)라고 밝히다 (indirect copula/name + news reporting)","exp":"reported speech. 계획이다 → 계획이라고 발표했습니다 = \\"announced that (it) is planned\\".","example_in_sentence":"계획이라고 발표했습니다"},{"type":"grammar","label":"~(으)ㄹ 전망이다 / 계획이다 / 방침이다 / 예정이다 (is expected / planned to)","exp":"formal future intent. 시작하다 → 시작할 계획이다 = \\"plans to begin\\".","example_in_sentence":"시작할 계획이라고"}]},{"text":"전 세계가 새로운 돈의 시대를 준비하고 있어요.","translation":"The whole world is preparing for a new era of money.","vocab":[{"ko":"시대","en":"era","note":""}],"analysis":[{"type":"grammar","label":"~고 있다 (continuous)","exp":"progressive. 준비하다 → 준비하고 있다 = \\"is preparing\\".","example_in_sentence":"준비하고 있어요"},{"type":"grammar","label":"~롭다 (-ous / adjective formative)","exp":"noun→adjective. 새 → 새롭다 → 새로운 = \\"new\\".","example_in_sentence":"새로운 돈"},{"type":"grammar","label":"~하고 (with/and, conv)","exp":"conversational. (Regex hit on 하고 in 준비하고.)","example_in_sentence":""}]}],"version":"s5"}', E'[{"ko":"정부","en":"government","note":""},{"ko":"자체","en":"own, in-house","note":""},{"ko":"화폐","en":"currency","note":""},{"ko":"도입","en":"introduction, adoption","note":""},{"ko":"새롭다","en":"to be new","note":"ㅂ-irregular: 새롭+은 → 새로운"},{"ko":"올해","en":"this year","note":""},{"ko":"전국","en":"the whole country","note":""},{"ko":"현재","en":"currently","note":""},{"ko":"세계","en":"world","note":""},{"ko":"인구","en":"population","note":""},{"ko":"약","en":"about, approximately","note":""},{"ko":"억","en":"hundred million","note":"14억 = 1.4 billion"},{"ko":"금융","en":"finance","note":""},{"ko":"저축하다","en":"to save (money)","note":""},{"ko":"편리하다","en":"to be convenient","note":""},{"ko":"유럽연합","en":"European Union","note":""},{"ko":"이미","en":"already","note":""},{"ko":"준비하다","en":"to prepare","note":""},{